sys_ws_operation.operation_script:
(function processRequest(request, response) {
    // Handle different request body structures
    var requestBody = request.body;
    if (requestBody.data && requestBody.data.data) {
        requestBody = requestBody.data.data;
    } else if (requestBody.data) {
        requestBody = requestBody.data;
    }

    gs.info("\ud83d\udd35 Incoming API Request to toggle complex property: " + JSON.stringify(requestBody));

    if (!requestBody || !requestBody.title) {
        gs.error("\u274c Missing required data: title");
        response.setStatus(400);
        response.setBody({ error: "Missing required data: title" });
        return;
    }

    var integrationTitle = requestBody.title;
    gs.info("\ud83d\udd39 Processing request for integration: " + integrationTitle);

    // Find System Property to Update
    var gr = new GlideRecord('sys_properties');
    gr.addQuery('name', 'sam.integration');
    gr.query();

    if (gr.next()) {
        // Get the current value
        var currentValue = gr.getValue('value');
        gs.info("\u2705 System Property Found: Current Value: " + currentValue);

        var integrationsArr;
        try {
            integrationsArr = JSON.parse(currentValue || '[]');
        } catch (e) {
            integrationsArr = [];
            gs.error("⚠️ Error parsing property value: " + e);
        }

        // Find the integration object by title
        var integrationObj = integrationsArr.find(obj => obj.title === integrationTitle);

        if (!integrationObj) {
            gs.error("❌ Integration not found: " + integrationTitle);
            response.setStatus(404);
            response.setBody({ error: "Integration not found: " + integrationTitle });
            return;
        }

        // Toggle the complex value
        integrationObj.complex = !integrationObj.complex;

        // Update the system property
        gr.setValue('value', JSON.stringify(integrationsArr));
        var updateResult = gr.update();

        if (updateResult) {
            gs.info("✅ Integration Successfully Updated! Title: " + integrationTitle + ", New Complex Value: " + integrationObj.complex);
            response.setStatus(200);
            response.setBody({ 
                success: true, 
                message: 'Updated successfully', 
                title: integrationTitle, 
                complex: integrationObj.complex 
            });
        } else {
            gs.error("❌ Update Failed for System Property");
            response.setStatus(500);
            response.setBody({ error: "Update failed for system property" });
        }
    } else {
        gs.warn("❌ System Property 'sam.integration' not found");
        response.setStatus(404);
        response.setBody({ error: "System property not found" });
    }
})(request, response);
